"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["35796"],{43877(e){e.exports=JSON.parse('{"id":"FIN-684","slug":"real-return","term":"Real Return","also_known_as":[],"difficulty":"Intermediate","definition":"Real return is the return on an investment after adjusting for inflation. It shows how much an investor\'s purchasing power has actually increased.","explanation":["An investment can grow in money terms while losing value in terms of what the money can buy. Real return removes the effect of rising prices.","A simple approximation is to subtract the inflation rate from the nominal return. If an investment earns 7% in a year when inflation is 3%, its real return is about 4%. The more precise calculation gives about 3.9%, because the investment\'s gain is also measured in money that has lost some value.","Real returns can be negative even when nominal returns are positive. A savings account paying 2% during a year of 5% inflation has a real return of about \u22123%, so the saver can buy less at the end of the year than at the start.","Real return is the most meaningful measure for long-term goals such as retirement, because what matters is the lifestyle savings can support, not the number in the account.","Historically, different asset classes have produced very different real returns over long periods. Shares have tended to outpace inflation by more than bonds or cash, but with much greater short-term volatility."],"note":"","total":1500,"prev":{"slug":"real-option","term":"Real Option"},"next":{"slug":"real-time-payment","term":"Real-Time Payment"}}')}}]);